  container-type: inline-size;
}

.control {
  padding: 16px;
  border-style: solid;
  border-width: 0 0 1px 0;
  border-bottom-color: rgb(195, 195, 195);
  background-color: white;
  /* ensure this stays */
  cursor: default;
  ;
}

.children {
  display: flex;
  flex-direction: row;
  gap: 16px;
  align-items: center;
  width: 100%;
  /* fill the .control container */
}

.label-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  min-width: 0;
  /* Allow shrinking below content min-size */
}

.label-row>label {
  font-size: 18px;
  font-weight: 700;
  min-width: 100px;
}

.label-row>span {
  min-width: 36px;
  font-size: 12pt;
  text-align: center;
}

.label-row>input {
  max-width: 95px;
}

.input-row {
  display: flex;
  flex-direction: row;
  gap: 8px;
  flex: 1;
  align-items: center;
}

.input-row>input,
.input-row>select {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
}

.input-row>button {
  flex: 0 0 auto;
  margin-left: 8px;
}

/* styles.css or styles.module.css */
/* styles.css or styles.module.css */
.checkerboard {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
  background-size: 24px 24px;
  padding: 4px;
  display: inline-block;
}

