@container (max-width: 450px) {
  .children {
    flex-direction: column;
    gap: 8px;
    align-items: stretch;
    width: 100%;
    /* ensure full width */
  }

  .label-row>input {
    max-width: 100%;
  }

  .label-row,
  .input-row {
    width: 100%;
    /* fill container to show background */
  }

  .label-row {
    justify-content: space-between;
    /* Heading | Value */
  }

  .input-row {
    justify-content: flex-start;
    /* Input | Reset | Tooltip */
  }
}

